 59→pub(crate) fn preview(
 60→    handlers: &[ConfiguredHandler],
 61→    request: &SessionStartRequest,
 62→) -> Vec<HookRunSummary> {
 63→    dispatcher::select_handlers(
 64→        handlers,
 65→        HookEventName::SessionStart,
 66→        Some(request.source.as_str()),
 67→    )
 68→    .into_iter()
