 73→pub(crate) async fn run(
 74→    handlers: &[ConfiguredHandler],
 75→    shell: &CommandShell,
 76→    request: SessionStartRequest,
 77→    turn_id: Option<String>,
 78→) -> SessionStartOutcome {
 79→    let matched = dispatcher::select_handlers(
 80→        handlers,
 81→        HookEventName::SessionStart,
 82→        Some(request.source.as_str()),
 83→    );
 84→    if matched.is_empty() {
 85→        return SessionStartOutcome {
 86→            hook_events: Vec::new(),
 87→            should_stop: false,
 88→            stop_reason: None,
 89→            additional_contexts: Vec::new(),
 90→        };
 91→    }
 92→
 93→    let input_json = match serde_json::to_string(&SessionStartCommandInput::new(
 94→        request.session_id.to_string(),
 95→        request.transcript_path.clone(),
 96→        request.cwd.display().to_string(),
 97→        request.model.clone(),
 98→        request.permission_mode.clone(),
 99→        request.source.as_str().to_string(),
100→    )) {
101→        Ok(input_json) => input_json,
102→        Err(error) => {
103→            return serialization_failure_outcome(common::serialization_failure_hook_events(
104→                matched,
105→                turn_id,
106→                format!("failed to serialize session start hook input: {error}"),
107→            ));
108→        }
109→    };
110→
111→    let results = dispatcher::execute_handlers(
112→        shell,
113→        matched,
114→        input_json,
115→        request.cwd.as_path(),
116→        turn_id,
117→        parse_completed,
118→    )
119→    .await;
120→
121→    let should_stop = results.iter().any(|result| result.data.should_stop);
122→    let stop_reason = results
123→        .iter()
124→        .find_map(|result| result.data.stop_reason.clone());
125→    let additional_contexts = common::flatten_additional_contexts(
126→        results
127→            .iter()
128→            .map(|result| result.data.additional_contexts_for_model.as_slice()),
129→    );
130→
131→    SessionStartOutcome {
132→        hook_events: results.into_iter().map(|result| result.completed).collect(),
133→        should_stop,
134→        stop_reason,
135→        additional_contexts,
136→    }
137→}
