139→fn parse_completed(
140→    handler: &ConfiguredHandler,
141→    run_result: CommandRunResult,
142→    turn_id: Option<String>,
143→) -> dispatcher::ParsedHandler<SessionStartHandlerData> {
144→    let mut entries = Vec::new();
145→    let mut status = HookRunStatus::Completed;
146→    let mut should_stop = false;
147→    let mut stop_reason = None;
148→    let mut additional_contexts_for_model = Vec::new();
149→
150→    match run_result.error.as_deref() {
151→        Some(error) => {
152→            status = HookRunStatus::Failed;
153→            entries.push(HookOutputEntry {
154→                kind: HookOutputEntryKind::Error,
155→                text: error.to_string(),
156→            });
157→        }
158→        None => match run_result.exit_code {
159→            Some(0) => {
160→                let trimmed_stdout = run_result.stdout.trim();
161→                if trimmed_stdout.is_empty() {
162→                } else if let Some(parsed) = output_parser::parse_session_start(&run_result.stdout)
163→                {
164→                    if let Some(system_message) = parsed.universal.system_message {
165→                        entries.push(HookOutputEntry {
166→                            kind: HookOutputEntryKind::Warning,
167→                            text: system_message,
168→                        });
169→                    }
170→                    if let Some(additional_context) = parsed.additional_context {
171→                        common::append_additional_context(
172→                            &mut entries,
173→                            &mut additional_contexts_for_model,
174→                            additional_context,
175→                        );
176→                    }
177→                    let _ = parsed.universal.suppress_output;
178→                    if !parsed.universal.continue_processing {
179→                        status = HookRunStatus::Stopped;
180→                        should_stop = true;
181→                        stop_reason = parsed.universal.stop_reason.clone();
182→                        if let Some(stop_reason_text) = parsed.universal.stop_reason {
183→                            entries.push(HookOutputEntry {
184→                                kind: HookOutputEntryKind::Stop,
185→                                text: stop_reason_text,
186→                            });
187→                        }
188→                    }
189→                // Preserve plain-text context support without treating malformed JSON as context.
190→                } else if trimmed_stdout.starts_with('{') || trimmed_stdout.starts_with('[') {
191→                    status = HookRunStatus::Failed;
192→                    entries.push(HookOutputEntry {
193→                        kind: HookOutputEntryKind::Error,
194→                        text: "hook returned invalid session start JSON output".to_string(),
195→                    });
196→                } else {
197→                    let additional_context = trimmed_stdout.to_string();
198→                    common::append_additional_context(
199→                        &mut entries,
200→                        &mut additional_contexts_for_model,
201→                        additional_context,
202→                    );
203→                }
204→            }
205→            Some(exit_code) => {
206→                status = HookRunStatus::Failed;
207→                entries.push(HookOutputEntry {
208→                    kind: HookOutputEntryKind::Error,
209→                    text: format!("hook exited with code {exit_code}"),
210→                });
211→            }
212→            None => {
213→                status = HookRunStatus::Failed;
214→                entries.push(HookOutputEntry {
215→                    kind: HookOutputEntryKind::Error,
216→                    text: "hook exited without a status code".to_string(),
217→                });
218→            }
219→        },
220→    }
221→
222→    let completed = HookCompletedEvent {
223→        turn_id,
224→        run: dispatcher::completed_summary(handler, &run_result, status, entries),
225→    };
226→
227→    dispatcher::ParsedHandler {
228→        completed,
229→        data: SessionStartHandlerData {
230→            should_stop,
231→            stop_reason,
232→            additional_contexts_for_model,
233→        },
234→    }
235→}
