237→fn serialization_failure_outcome(hook_events: Vec<HookCompletedEvent>) -> SessionStartOutcome {
238→    SessionStartOutcome {
239→        hook_events,
240→        should_stop: false,
241→        stop_reason: None,
242→        additional_contexts: Vec::new(),
243→    }
244→}
