 80→export function resolveCliBinary(
 81→  provider: CliProvider,
 82→  config: CliConfig | null | undefined,
 83→  env: Record<string, string | undefined>,
 84→): string {
 85→  const providerConfig = getCliProviderConfig(provider, config);
 86→  if (isNonEmptyString(providerConfig?.binary)) return providerConfig.binary.trim();
 87→  const pathKey = PROVIDER_PATH_ENV[provider];
 88→  if (isNonEmptyString(env[pathKey])) return env[pathKey].trim();
 89→  const envKey = `SUMMARIZE_CLI_${provider.toUpperCase()}`;
 90→  if (isNonEmptyString(env[envKey])) return env[envKey].trim();
 91→  return DEFAULT_BINARIES[provider];
 92→}
