136→export async function runCliModel({
137→  provider,
138→  prompt,
139→  model,
140→  allowTools,
141→  timeoutMs,
142→  env,
143→  execFileImpl,
144→  config,
145→  cwd,
146→  extraArgs,
147→}: RunCliModelOptions): Promise<CliRunResult> {
148→  const execFileFn = execFileImpl ?? execFile;
149→  const binary = resolveCliBinary(provider, config, env);
150→  const args: string[] = [];
151→
152→  const effectiveEnv =
153→    provider === "gemini" && !isNonEmptyString(env.GEMINI_CLI_NO_RELAUNCH)
154→      ? { ...env, GEMINI_CLI_NO_RELAUNCH: "true" }
155→      : env;
156→
157→  const providerConfig = getCliProviderConfig(provider, config);
158→  const requestedModel = isNonEmptyString(model)
159→    ? model.trim()
160→    : isNonEmptyString(providerConfig?.model)
161→      ? providerConfig.model.trim()
162→      : null;
163→  const providerExtraArgs: string[] = [];
164→  if (providerConfig?.extraArgs?.length) {
165→    providerExtraArgs.push(...providerConfig.extraArgs);
166→  }
167→  if (extraArgs?.length) {
168→    providerExtraArgs.push(...extraArgs);
169→  }
170→  if (provider === "openclaw") {
171→    const openclawArgs = [
172→      ...providerExtraArgs,
173→      "agent",
174→      "--agent",
175→      requestedModel ?? "main",
176→      "-",
177→      "--json",
178→      "--timeout",
179→      String(Math.max(1, Math.ceil(timeoutMs / 1000))),
180→    ];
181→    const { stdout } = await execCliWithInput({
182→      execFileImpl: execFileFn,
183→      cmd: binary,
184→      args: openclawArgs,
185→      input: prompt,
186→      timeoutMs,
187→      env: effectiveEnv,
188→      cwd,
189→    });
190→    const parsed = JSON.parse(stdout);
191→    const payloads = parsed?.result?.payloads;
192→    const text = Array.isArray(payloads)
193→      ? payloads
194→          .map((p) => (typeof p?.text === "string" ? p.text : ""))
195→          .filter(Boolean)
196→          .join("\n\n")
197→      : "";
198→    if (!text.trim()) throw new Error("OpenClaw CLI returned empty output");
199→    const usage =
200→      parsed?.result?.meta?.agentMeta?.lastCallUsage ??
201→      parsed?.result?.meta?.agentMeta?.usage ??
202→      null;
203→    return { text: text.trim(), usage, costUsd: null };
204→  }
205→
206→  if (provider === "opencode") {
207→    const isolatedCwd =
208→      !allowTools && !cwd ? await fs.mkdtemp(path.join(tmpdir(), "summarize-opencode-")) : null;
209→    try {
210→      args.push("run", ...providerExtraArgs, "--format", "json");
211→      if (requestedModel) {
212→        args.push("--model", requestedModel);
213→      }
214→      const { stdout } = await execCliWithInput({
215→        execFileImpl: execFileFn,
216→        cmd: binary,
217→        args,
218→        input: prompt,
219→        timeoutMs,
220→        env: effectiveEnv,
221→        cwd: isolatedCwd ?? cwd,
222→      });
223→      return parseOpenCodeOutputFromJsonl(stdout);
224→    } finally {
225→      if (isolatedCwd) {
226→        await fs.rm(isolatedCwd, { recursive: true, force: true }).catch(() => {});
227→      }
228→    }
229→  }
230→
231→  if (provider === "codex") {
232→    const outputDir = await fs.mkdtemp(path.join(tmpdir(), "summarize-codex-"));
233→    const outputPath = path.join(outputDir, "last-message.txt");
234→    args.push(...providerExtraArgs);
235→    args.push("exec", "--output-last-message", outputPath, "--skip-git-repo-check", "--json");
236→    if (requestedModel) {
237→      args.push("-m", requestedModel);
238→    }
239→    const hasVerbosityOverride = args.some((arg) => arg.includes("text.verbosity"));
240→    if (!hasVerbosityOverride) {
241→      args.push("-c", 'text.verbosity="medium"');
242→    }
243→    const { stdout } = await execCliWithInput({
244→      execFileImpl: execFileFn,
245→      cmd: binary,
246→      args,
247→      input: prompt,
248→      timeoutMs,
249→      env: effectiveEnv,
250→      cwd,
251→    });
252→    const { usage, costUsd } = parseCodexUsageFromJsonl(stdout);
253→    let fileText = "";
254→    try {
255→      fileText = (await fs.readFile(outputPath, "utf8")).trim();
256→    } catch {
257→      fileText = "";
258→    }
259→    if (fileText) {
260→      return { text: fileText, usage, costUsd };
261→    }
262→    const parsedStdout = parseCodexOutputFromJsonl(stdout);
263→    if (parsedStdout.text) {
264→      return { text: parsedStdout.text, usage, costUsd };
265→    }
266→    if (parsedStdout.sawStructuredEvent) {
267→      throw new Error("CLI returned empty output");
268→    }
269→    const stdoutText = stdout.trim();
270→    if (stdoutText) {
271→      return { text: stdoutText, usage, costUsd };
272→    }
273→    throw new Error("CLI returned empty output");
274→  }
275→
276→  if (!isJsonCliProvider(provider)) {
277→    throw new Error(`Unsupported CLI provider "${provider}".`);
278→  }
279→  args.push(...providerExtraArgs);
280→  const input = appendJsonProviderArgs({
281→    provider,
282→    args,
283→    allowTools,
284→    model: requestedModel,
285→    prompt,
286→  });
287→
288→  const { stdout } = await execCliWithInput({
289→    execFileImpl: execFileFn,
290→    cmd: binary,
291→    args,
292→    input,
293→    timeoutMs,
294→    env: effectiveEnv,
295→    cwd,
296→  });
297→  return parseJsonProviderOutput({ provider, stdout });
298→}
