 10→function toUtf8String(value: string | Buffer): string {
 11→  return typeof value === "string" ? value : value.toString("utf8");
 12→}
 13→
 14→function formatErrorMessageWithStderr(
 15→  message: string,
 16→  stderrText: string,
 17→  separator: ": " | "\n" = ": ",
 18→): string {
 19→  const trimmedStderr = stderrText.trim();
 20→  if (!trimmedStderr || message.includes(trimmedStderr)) return message;
 21→  return `${message}${separator}${trimmedStderr}`;
 22→}
 23→
 24→function formatTimeoutLabel(timeoutMs: number): string {
 25→  if (Number.isFinite(timeoutMs) && timeoutMs > 0) {
 26→    if (timeoutMs % 60_000 === 0) return `${Math.floor(timeoutMs / 60_000)}m`;
 27→    if (timeoutMs % 1000 === 0) return `${Math.floor(timeoutMs / 1000)}s`;
 28→    return `${Math.floor(timeoutMs)}ms`;
 29→  }
 30→  return "unknown time";
 31→}
 32→
 33→function getExecErrorCodeText(error: CliExecError): string {
 34→  if (typeof error.code === "string") return error.code;
 35→  if (Buffer.isBuffer(error.code)) return toUtf8String(error.code);
 36→  if (typeof error.code === "number") return String(error.code);
 37→  return "";
 38→}
 39→
 40→function isExecTimeoutError(error: CliExecError): boolean {
 41→  if (getExecErrorCodeText(error).toUpperCase() === "ETIMEDOUT") return true;
 42→  return error.killed === true && error.signal === "SIGTERM";
 43→}
 44→
 45→function getExecErrorMessage(error: CliExecError): string {
 46→  return typeof error.message === "string" && error.message.trim().length > 0
 47→    ? error.message.trim()
 48→    : "CLI command failed";
 49→}
 50→
 51→function getExecCommand(error: CliExecError, cmd: string, args: string[]): string {
 52→  return typeof error.cmd === "string" && error.cmd.trim().length > 0
 53→    ? error.cmd.trim()
 54→    : [cmd, ...args].join(" ");
 55→}
