 57→export async function execCliWithInput({
 58→  execFileImpl,
 59→  cmd,
 60→  args,
 61→  input,
 62→  timeoutMs,
 63→  env,
 64→  cwd,
 65→}: {
 66→  execFileImpl: ExecFileFn;
 67→  cmd: string;
 68→  args: string[];
 69→  input: string;
 70→  timeoutMs: number;
 71→  env: Record<string, string | undefined>;
 72→  cwd?: string;
 73→}): Promise<{ stdout: string; stderr: string }> {
 74→  return await new Promise((resolve, reject) => {
 75→    const child = execFileImpl(
 76→      cmd,
 77→      args,
 78→      {
 79→        timeout: timeoutMs,
 80→        env: { ...process.env, ...env },
 81→        cwd,
 82→        maxBuffer: 50 * 1024 * 1024,
 83→      },
 84→      (error, stdout, stderr) => {
 85→        const stderrText = toUtf8String(stderr);
 86→        if (error) {
 87→          if (isExecTimeoutError(error)) {
 88→            const timeoutMessage =
 89→              `CLI command timed out after ${formatTimeoutLabel(timeoutMs)}: ${getExecCommand(error, cmd, args)}. ` +
 90→              "Increase --timeout (e.g. 5m).";
 91→            reject(
 92→              new Error(formatErrorMessageWithStderr(timeoutMessage, stderrText, "\n"), {
 93→                cause: error,
 94→              }),
 95→            );
 96→            return;
 97→          }
 98→          reject(
 99→            new Error(formatErrorMessageWithStderr(getExecErrorMessage(error), stderrText), {
100→              cause: error,
101→            }),
102→          );
103→          return;
104→        }
105→        resolve({ stdout: toUtf8String(stdout), stderr: stderrText });
106→      },
107→    );
108→    if (child.stdin) {
109→      child.stdin.write(input);
110→      child.stdin.end();
111→    }
112→  });
113→}
