696→// shouldCondenseWithOverlapCheck returns true if the session should be condensed
697→// into this commit. Active sessions with recent interaction always condense
698→// (bypasses overlap check). Stale ACTIVE and IDLE/ENDED sessions require
699→// file overlap evidence between tracked files and committed files.
700→func (h *postCommitActionHandler) shouldCondenseWithOverlapCheck(isActive bool, lastInteraction *time.Time) bool {
701→	if !h.hasNew {
702→		return false
703→	}
704→	// ACTIVE sessions with recent interaction: skip the overlap check.
705→	// PrepareCommitMsg already validated this commit is session-related
706→	// (added trailer). The overlap check is only meaningful when we need
707→	// heuristic evidence that a commit was related to the session.
708→	//
709→	// We check LastInteractionTime to avoid condensing stale ACTIVE sessions
710→	// (agent killed without Stop hook) into every subsequent commit. A stale
711→	// session has no recent interaction and falls through to the overlap check.
712→	if isActive && isRecentInteraction(lastInteraction) {
713→		return true
714→	}
715→	if len(h.filesTouchedBefore) == 0 {
716→		return false // No files tracked = no overlap evidence
717→	}
718→	// Only check files that were actually changed in this commit.
719→	// Without this, files that exist in the tree but weren't changed
720→	// would pass the "modified file" check in filesOverlapWithContent
721→	// (because the file exists in the parent tree), causing stale
722→	// sessions to be incorrectly condensed.
723→	var committedTouchedFiles []string
724→	for _, f := range h.filesTouchedBefore {
725→		if _, ok := h.committedFileSet[f]; ok {
726→			committedTouchedFiles = append(committedTouchedFiles, f)
727→		}
728→	}
729→	if len(committedTouchedFiles) == 0 {
730→		return false
731→	}
732→	return filesOverlapWithContent(h.ctx, h.repo, h.shadowBranchName, h.commit, committedTouchedFiles, overlapOpts{
733→		headTree:      h.headTree,
734→		shadowTree:    h.shadowTree,
